import{_ as a,b as l,c as t,d as i}from"./chunks/framework.D4cM_aKq.js";const p=JSON.parse('{"title":"拾知 · 知识检索实验","description":"从整理资料到找到答案，探索个人知识库与语义检索的连接方式。","frontmatter":{"layout":"project","title":"拾知 · 知识检索实验","description":"从整理资料到找到答案，探索个人知识库与语义检索的连接方式。","date":"2026-10-16","category":"人工智能","directory":"知识应用","tags":["Python","RAG","知识管理"],"cover":"network","featured":true,"sample":true},"headers":[{"level":2,"title":"想解决的问题","slug":"想解决的问题","link":"#想解决的问题","children":[]},{"level":2,"title":"一条可能的实现路径","slug":"一条可能的实现路径","link":"#一条可能的实现路径","children":[]},{"level":2,"title":"需要验证的关键点","slug":"需要验证的关键点","link":"#需要验证的关键点","children":[{"level":3,"title":"找到的内容是否相关","slug":"找到的内容是否相关","link":"#找到的内容是否相关","children":[]},{"level":3,"title":"回答能否追溯来源","slug":"回答能否追溯来源","link":"#回答能否追溯来源","children":[]}]},{"level":2,"title":"展示建议","slug":"展示建议","link":"#展示建议","children":[]},{"level":2,"title":"相关笔记","slug":"相关笔记","link":"#相关笔记","children":[]}],"relativePath":"projects/ai/knowledge-lab.md","filePath":"projects/ai/knowledge-lab.md"}'),r={name:"projects/ai/knowledge-lab.md"};function o(n,e,d,h,s,c){return l(),t("div",null,[...e[0]||(e[0]=[i('<h2 id="想解决的问题" tabindex="-1">想解决的问题 <a class="header-anchor" href="#想解决的问题" aria-label="Permalink to &quot;想解决的问题&quot;">​</a></h2><p>当笔记、文档和项目资料不断增加，关键词搜索有时无法找到表达不同但含义相近的内容。这个示例展示一项知识检索实验可以如何记录，尚未接入真实模型服务。</p><h2 id="一条可能的实现路径" tabindex="-1">一条可能的实现路径 <a class="header-anchor" href="#一条可能的实现路径" aria-label="Permalink to &quot;一条可能的实现路径&quot;">​</a></h2><ol><li>清洗并拆分文档，保留标题、来源与章节位置。</li><li>将文档片段转为向量，建立可检索的索引。</li><li>对输入问题同时进行关键词与语义检索。</li><li>把候选资料交给生成模型，并展示可追溯的引用。</li></ol><h2 id="需要验证的关键点" tabindex="-1">需要验证的关键点 <a class="header-anchor" href="#需要验证的关键点" aria-label="Permalink to &quot;需要验证的关键点&quot;">​</a></h2><h3 id="找到的内容是否相关" tabindex="-1">找到的内容是否相关 <a class="header-anchor" href="#找到的内容是否相关" aria-label="Permalink to &quot;找到的内容是否相关&quot;">​</a></h3><p>先建立一组能够人工判断的问题与参考资料，再比较不同切分策略下的检索结果。不要只凭最终回答的流畅程度判断系统效果。</p><h3 id="回答能否追溯来源" tabindex="-1">回答能否追溯来源 <a class="header-anchor" href="#回答能否追溯来源" aria-label="Permalink to &quot;回答能否追溯来源&quot;">​</a></h3><p>展示原文片段、文件名称和章节，使读者能检查回答依据。没有足够资料时，应明确表示证据不足。</p><h2 id="展示建议" tabindex="-1">展示建议 <a class="header-anchor" href="#展示建议" aria-label="Permalink to &quot;展示建议&quot;">​</a></h2><p>实际发布这个项目时，可以加入检索界面截图、数据处理流程和真实评估结果。若要提供在线模型推理，需要另行部署后端服务；GitHub Pages 上可以展示前端与项目说明。</p><h2 id="相关笔记" tabindex="-1">相关笔记 <a class="header-anchor" href="#相关笔记" aria-label="Permalink to &quot;相关笔记&quot;">​</a></h2><p>继续阅读 <a href="/journal/ai/rag-basics.html">RAG：先找到资料，再组织答案</a>。</p>',13)])])}const b=a(r,[["render",o]]);export{p as __pageData,b as default};
